import itertools, math, time

n = 24
fixed_seq = {9: -1, 14: 1, 15: -1, 22: -1}
fixed_c = {3: 0, 9: -2, 14: -1, 19: 0}

# map seq value to bit: +1 -> 1, -1 -> 0
fixed_bits = {i: 1 if v == 1 else 0 for i, v in fixed_seq.items()}

free_indices = [i for i in range(n) if i not in fixed_bits]
print("Free indices:", free_indices, "count:", len(free_indices))

# Precompute masks for each lag
lag_masks = {}
for k in range(1, n):
    lag_masks[k] = (1 << (n - k)) - 1

def seq_from_mask(mask):
    # returns list of +1/-1
    arr = []
    for i in range(n):
        if i in fixed_bits:
            arr.append(1 if fixed_bits[i] else -1)
        else:
            # extract bit for this free index
            # We need to know position in free_indices
            pass
    return arr

# To avoid building sequence array each time, we can construct full 24-bit integer from mask.
# Let's map free index j to bit position in mask.
free_pos = {idx: p for p, idx in enumerate(free_indices)}

def build_full_mask(mask):
    # mask has bits for free indices
    full = 0
    for idx in free_indices:
        if (mask >> free_pos[idx]) & 1:
            full |= (1 << idx)
    for idx, bit in fixed_bits.items():
        if bit:
            full |= (1 << idx)
    return full

# Let's test build_full_mask
