# Precompute full masks for all possibilities? That's 2^20 entries, 4MB if 4 bytes each, manageable.
# But building on the fly might be okay.

# Let's do a quick performance test with a small subset.
def compute_cs(full_mask):
    cs = {}
    for k in range(1, n):
        disagreements = ((full_mask ^ (full_mask >> k)) & lag_masks[k]).bit_count()
        cs[k] = (n - k) - 2 * disagreements
    return cs

